function APR.event.functions.accept(event, ...)
    if event == "QUEST_ACCEPTED" then
        local questID = ...;
        local profile = APR:GetSettingsProfile()

        local function queueQuestShare()
            if not profile or not profile.autoShareQuestWithFriend or not IsInGroup() then
                return
            end
            if not (C_QuestLog.IsPushableQuest and C_QuestLog.IsPushableQuest(questID)) then
                return
            end
            if not APR.party:CheckIfPartyMemberIsFriend() then
                return
            end

            for i = 1, #questShareQueue do
                if questShareQueue[i] == questID then
                    return
                end
            end

            table.insert(questShareQueue, questID)
            questShareRetries[questID] = 0
        end--[[APR_DIAG]]; queueQuestShare = APRTrace("APR-Core/core/Event.lua:310:queueQuestShare#12", queueQuestShare)--[[/APR_DIAG]]

        if profile and profile.firstAutoShareQuestWithFriend and IsInGroup() then
            APR.questionDialog:CreateQuestionPopup("SHOW_GROUP_SHAREWITHFRIEND_FIRSTTIME",
                L["SHOW_GROUP_SHAREWITHFRIEND_FIRSTTIME"], --[[APR_DIAG]]APRTrace("APR-Core/core/Event.lua:333:callback#13", --[[/APR_DIAG]]function()
                    profile.autoShareQuestWithFriend = true
                    queueQuestShare()
                end--[[APR_DIAG]])--[[/APR_DIAG]])
            profile.firstAutoShareQuestWithFriend = false
        end
        queueQuestShare()

        APR:HandleTemporaryRouteTriggerQuestAccepted(questID)

        APR:Debug(string.format(L["Q_ACCEPTED"], questID))
        C_Timer.After(0.2, --[[APR_DIAG]]APRTrace("APR-Core/core/Event.lua:344:callback#14", --[[/APR_DIAG]]function() APR:UpdateMapId() end--[[APR_DIAG]])--[[/APR_DIAG]])
    end

    if event == "QUEST_ACCEPT_CONFIRM" then -- escort quest
        if IsModifierKeyDown() then return end
        if autoAccept or autoAcceptRoute then
            C_Timer.After(0.2, --[[APR_DIAG]]APRTrace("APR-Core/core/Event.lua:350:callback#15", --[[/APR_DIAG]]function() APR:AcceptQuest() end--[[APR_DIAG]])--[[/APR_DIAG]])
        end
    end
end--[[APR_DIAG]]; APR.event.functions.accept = APRTrace("APR-Core/core/Event.lua:305:APR.event.functions.accept#11", APR.event.functions.accept)--[[/APR_DIAG]]

function APR.event.functions.achievement(event, ...)
    if event == "ACHIEVEMENT_EARNED" then APR:RefreshLevelProfileTargets() end
    local achievementData = step and step.Achievement
    if not achievementData or not achievementData.achievementID then
        return
    end

    local achievementID = achievementData.achievementID
    if event == "CRITERIA_COMPLETE" then
        local completedCriteriaID = ...
        local expectedCriteriaID = achievementData.criteriaID
        if not expectedCriteriaID then
            expectedCriteriaID = select(3, APR:GetAchievementCriteriaInfo(achievementData))
        end
        if completedCriteriaID ~= expectedCriteriaID then
            return
        end
    elseif event == "CRITERIA_EARNED" then
        local earnedAchievementID = ...
        if earnedAchievementID ~= achievementID then
            return
        end
    elseif event == "ACHIEVEMENT_EARNED" then
        local earnedAchievementID = ...
        if earnedAchievementID ~= achievementID then
            return
        end
    else
        return
    end

    local expectedRoute = APR.ActiveRoute
    local playerData = APRData and APRData[APR.PlayerID]
    local expectedStepIndex = playerData and expectedRoute and playerData[expectedRoute]

    if not expectedStepIndex then
        return
    end

    C_Timer.After(0.3, --[[APR_DIAG]]APRTrace("APR-Core/core/Event.lua:394:callback#17", --[[/APR_DIAG]]function()
        local currentPlayerData = APRData and APRData[APR.PlayerID]

        -- Ignore stale or duplicate achievement events after the route step has advanced.
        if APR.ActiveRoute ~= expectedRoute
            or not currentPlayerData
            or currentPlayerData[expectedRoute] ~= expectedStepIndex then
            return
        end

        local currentStep = APR:GetStep(expectedStepIndex)
        local isCompleted = APR:IsAchievementStepComplete(currentStep)
        if isCompleted then
            APR:UpdateNextStep()
        end
    end--[[APR_DIAG]])--[[/APR_DIAG]])
end--[[APR_DIAG]]; APR.event.functions.achievement = APRTrace("APR-Core/core/Event.lua:355:APR.event.functions.achievement#16", APR.event.functions.achievement)--[[/APR_DIAG]]

function APR.event.functions.adventureMapAccept(event, followerTypeID)
    if IsModifierKeyDown() then
        return
    end
    if not autoAcceptRoute and not autoAccept then
        return
    end

    local isPickup = APR:IsPickupStep()
    local isAdventureMapStep = step and step.IsAdventureMap or false
    APR:Debug("AdventureMap: isPickup=" ..
        tostring(isPickup) .. " isAdventureMapStep=" .. tostring(isAdventureMapStep) .. " step=" .. tostring(step ~= nil))

    -- Block if the current step is not a pickup and not an adventure map step (unless autoAccept is on)
    if APR.ActiveRoute and not autoAccept and not isPickup and not isAdventureMapStep then
        APR:Debug("AdventureMap: step is not a pickup/adventureMap step and autoAccept is off, closing map")
        C_AdventureMap.Close();
        CancelAdventureMapRetries()
        APR:NotYet()
        return
    end

    -- Ensure the quest pool is built before checking adventure map quests
    local pool = APR:EnsureQuestPool()
    local poolIds = pool and pool.ids or {}
    if #poolIds > 0 then
        local ids = {}
        for _, id in ipairs(poolIds) do ids[#ids + 1] = tostring(id) end
        APR:Debug("AdventureMap: pool questIDs=[" .. table.concat(ids, ", ") .. "]")
    end

    local MAX_RETRIES = 10
    local RETRY_DELAY = 0.3
    local attempt = 0

    local retryToken = adventureMapRetryToken

    local function tryAcceptAdventureMapQuests()
        if retryToken ~= adventureMapRetryToken then
            APR:Debug("AdventureMap: retry cancelled (token mismatch)")
            return
        end

        attempt = attempt + 1
        -- Treat an unavailable choice count as empty so the existing retries can continue.
        local numChoices = C_AdventureMap.GetNumZoneChoices() or 0
        APR:Debug("AdventureMap: attempt " .. attempt .. "/" .. MAX_RETRIES .. " - choices: " .. numChoices)

        local questStarted = false
        for choiceIndex = 1, numChoices do
            local questID, textureKit, name, zoneDescription, normalizedX, normalizedY = C_AdventureMap
                .GetZoneChoiceInfo(choiceIndex);
            APR:Debug("AdventureMap: choice " ..
                choiceIndex .. " questID=" .. tostring(questID) .. " name=" .. tostring(name))

            -- Check if Blizzard's validation function exists before calling it
            local isQuestValid = true
            if AdventureMap_IsQuestValid then
                isQuestValid = AdventureMap_IsQuestValid(questID, normalizedX, normalizedY)
            end

            if isQuestValid then
                local inPool = APR:IsQuestInPool(tonumber(questID))
                -- Accept if quest is in the route pool, OR if autoAccept (accept all quests) is enabled
                if inPool or autoAccept then
                    APR:Debug("AdventureMap: starting quest " .. tostring(questID))
                    C_AdventureMap.StartQuest(questID)
                    questStarted = true
                end
            else
                APR:Debug("AdventureMap: questID=" ..
                    tostring(questID) .. " is not valid (AdventureMap_IsQuestValid=false)")
            end
        end

        -- Retry if no choices were available or no quest was started
        if not questStarted and attempt < MAX_RETRIES and retryToken == adventureMapRetryToken then
            APR:Debug("AdventureMap: no quest started, scheduling retry " .. (attempt + 1))
            C_Timer.After(RETRY_DELAY, tryAcceptAdventureMapQuests)
        elseif questStarted then
            APR:Debug("AdventureMap: quest(s) started successfully")
        elseif attempt >= MAX_RETRIES then
            APR:Debug("AdventureMap: max retries reached, giving up")
        end
    end--[[APR_DIAG]]; tryAcceptAdventureMapQuests = APRTrace("APR-Core/core/Event.lua:449:tryAcceptAdventureMapQuests#19", tryAcceptAdventureMapQuests)--[[/APR_DIAG]]

    -- the frame is actually shown, so IsShown() returns false at this point.
    -- The retry function checks it on each attempt once the frame has time to render.
    if retryToken == adventureMapRetryToken then
        C_Timer.After(RETRY_DELAY, tryAcceptAdventureMapQuests)
    else
        APR:Debug("AdventureMap: token mismatch at start, skipping")
    end
end--[[APR_DIAG]]; APR.event.functions.adventureMapAccept = APRTrace("APR-Core/core/Event.lua:412:APR.event.functions.adventureMapAccept#18", APR.event.functions.adventureMapAccept)--[[/APR_DIAG]]

