function APR.event.functions.spec(event, unit)
    if unit ~= "player" then return end

    local currentSpec = APR:GetClassSpecName()
    if not currentSpec then return end

    local foundRoutes = APR:FindAllSpecRoutesInCustomPath()
    if #foundRoutes == 0 then return end

    local replacements = APR:ResolveSpecRouteReplacements(currentSpec, foundRoutes)
    if #replacements == 0 then return end

    local i = 1
    local function ShowNextPopup()
        local data = replacements[i]
        if not data then
            if APR.routeconfig then
                APR.routeconfig:SendMessage("APR_Custom_Path_Update")
            end
            return
        end


        APR.questionDialog:CreateQuestionPopup("SPEC_ROUTE_CHANGE_PROMPT" .. i,
            string.format(
                L["SPEC_ROUTE_CHANGE_PROMPT"],
                data.oldDisplay,
                data.newDisplay
            ),
            --[[APR_DIAG]]APRTrace("APR-Core/core/Event.lua:1055:callback#68", --[[/APR_DIAG]]function()
                -- accept
                APRCustomPath[APR.PlayerID][data.index] = data.newDisplay

                -- Reset route if is you active route
                if data.index == 1 then
                    local newRouteKey = data.newRouteKey
                    if newRouteKey then
                        APR:ActivateRoute(newRouteKey)
                        APR:ResetRoute(APR.ActiveRoute)
                    end
                end
                i = i + 1
                ShowNextPopup()
            end--[[APR_DIAG]])--[[/APR_DIAG]],
            --[[APR_DIAG]]APRTrace("APR-Core/core/Event.lua:1070:callback#69", --[[/APR_DIAG]]function()
                -- cancel
                i = i + 1
                ShowNextPopup()
            end--[[APR_DIAG]])--[[/APR_DIAG]]
        )
    end--[[APR_DIAG]]; ShowNextPopup = APRTrace("APR-Core/core/Event.lua:1039:ShowNextPopup#67", ShowNextPopup)--[[/APR_DIAG]]

    ShowNextPopup()
end--[[APR_DIAG]]; APR.event.functions.spec = APRTrace("APR-Core/core/Event.lua:1026:APR.event.functions.spec#66", APR.event.functions.spec)--[[/APR_DIAG]]

function APR.event.functions.spell(event, unitTarget, castGUID, spellID)
    if not APRSecret:CanAccessValue(unitTarget) or not APRSecret:CanAccessValue(spellID) then return end
    if step and step.SpellETA then APR:HandleSpellETA(step, unitTarget, spellID) end
    if step and step.TameBeast then APR:HandleTameBeast(step, event, unitTarget, spellID) end
    if step and step.TameBeast and unitTarget == "player" then APR.event:QueueStepRefresh() end
    if unitTarget == "player" and step then
        if step.UseGarrisonHS and APR:IsTravelActionSpell("UseGarrisonHS", spellID) then
            APR:UpdateNextStep()
            return
        end
        if step.UseDalaHS and APR:IsTravelActionSpell("UseDalaHS", spellID) then
            APR:UpdateNextStep()
            return
        end
        local itemSpellID = step.UseItem and step.UseItem.itemSpellID
        if step.UseItem and not itemSpellID then
            local getItemSpell = C_Item and C_Item.GetItemSpell or GetItemSpell
            if getItemSpell then
                local _, id = getItemSpell(step.UseItem.itemID)
                itemSpellID = id
            end
        end
        local hearthstoneCast = step.UseHS and APR:IsHearthstoneSpell(spellID)
        if hearthstoneCast or
            (step.SpellTrigger and spellID == step.SpellTrigger) or
            (step.UseSpell and spellID == step.UseSpell.spellID) or
            (itemSpellID and spellID == itemSpellID)
        then
            APR:UpdateNextStep()
        end
    end
end--[[APR_DIAG]]; APR.event.functions.spell = APRTrace("APR-Core/core/Event.lua:1081:APR.event.functions.spell#70", APR.event.functions.spell)--[[/APR_DIAG]]

